-- ====================================================================
-- PhoneNest — Database đầy đủ (Schema + Migration 03..32 + Dữ liệu demo)
--
-- NỘI DUNG
--   * Schema đã gồm migration 03, 05-09, 11, 12, 15-32 (pn_migration_log có M12/M15/M16).
--     M24: YeuCauHauMai.maKh (chủ sở hữu) + maDonHang cho phép NULL; M25: trạng thái kiểm tra/xác minh + ketQuaXuLy. M26 adds after-sales assignment storage.
--     M27-M31 (thanh toán VNPay): ThanhToan.maGiaoDichNganHang + cột hoàn VNPay, trạng thái đơn CHO_THANH_TOAN,
--     bảng PhienThanhToan (checkout trả trước), trạng thái DANG_HOAN_TIEN, cột hoàn VNPay trên YeuCauDoiTra.
--   * 44 bảng (M21 cần MariaDB >= 11.7 vì kiểu VECTOR). Dữ liệu demo (cập nhật 15/11/2026):
--       - 75 sản phẩm đang bán, 433 phiên bản (RAM/ROM/màu) có giá tham khảo từ nhà bán lẻ chính hãng
--         (CellphoneS / Thế Giới Di Động, nguồn ghi ở PhienBanSanPham.nguonXacMinh), đã phê duyệt bán (APPROVED).
--       - 249 ảnh chụp sản phẩm thật theo màu (không ảnh quảng cáo / logo AI): đường dẫn /catalog/<maSanPham>/<mau>.webp, file nằm trong
--         BE/phonenest/src/main/resources/catalog (đóng gói cùng backend, KHÔNG nằm trong uploads/).
--         Ảnh Admin tải lên sau này lưu ở /uploads (thư mục app.upload-dir), không ảnh hưởng ảnh gốc.
--       - 100 sản phẩm ngừng bán làm dữ liệu mẫu.
--       - Tài khoản: admin@phonenest.vn, khach1@, khach2@, luuvanquoc9999@ (bộ cũ của bandienthoai) +
--         admin@phonenest.com, an@, binh@, hoang@ (bộ cũ của phonenest_full.sql, mật khẩu giữ nguyên).
--       - Khách hàng, địa chỉ, 34 tỉnh / phường xã, phí vận chuyển theo 4 vùng (M22, đủ 34 tỉnh + mức mặc định), voucher theo M23 (giảm tiền mặt theo bậc / % có trần).
--       - KHÔNG có đơn hàng / giỏ hàng / đánh giá cũ (dữ liệu thử nghiệm đã dọn).
--
-- QUY TẮC AN TOÀN
--   1. Không có DROP DATABASE / CREATE DATABASE / USE: chỉ định database đích trên dòng lệnh.
--   2. CREATE TABLE nghiêm ngặt (không IF NOT EXISTS) + kiểm tra database trống ngay đầu file:
--      database đã có bảng -> dừng ngay, không ghi gì.
--   3. Chỉ INSERT INTO (không INSERT IGNORE / REPLACE INTO).
--
-- CÁCH IMPORT
--   CREATE DATABASE BanDienThoai CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
--   mariadb -h 127.0.0.1 -P 3307 -u root -p BanDienThoai < DB/phonenest_full.sql
-- ====================================================================

SET NAMES utf8mb4;

-- FAIL-FAST GUARD: database đích phải TRỐNG.
SET @table_count = (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE());
SET @abort_sql = IF(@table_count > 0,
    'DO (SELECT 1 FROM `ABORT_ERROR_TARGET_DATABASE_IS_NOT_EMPTY_PLEASE_IMPORT_TO_EMPTY_DATABASE`)',
    'SELECT "Target database is empty. Safe to proceed with import." AS safe_import_status'
);
PREPARE stmt_empty_check FROM @abort_sql;
EXECUTE stmt_empty_check;
DEALLOCATE PREPARE stmt_empty_check;

SET FOREIGN_KEY_CHECKS = 0;

/*M!999999\- enable the sandbox mode */ 

